centerMap() {
    if (this.hasBoundsValue) {
        let bounds = this.boundsValue

        this.flyToBounds([
            [bounds.southWestLon, bounds.southWestLat],
            [bounds.northEastLon, bounds.northEastLat],
        ])
    }

    if (this.hasProblemValue) {
        let problem = this.problemValue

        this.map.flyTo({
            center: [problem.lon, problem.lat],
            zoom: 20,
            speed: 2,
        })

        if (!this.contributeValue) {
            // FIXME: make it DRY
            const coordinates = [problem.lon, problem.lat]
            var name = problem.name
            if (this.localeValue == "en" && problem.nameEn) {
                name = problem.nameEn
            }
            const html = `<a href="/${
                this.localeValue
            }/redirects/new?problem_id=${problem.id}" target="_blank">${
                name || ""
            }</a><span class="text-gray-400 ml-1">${problem.grade}</span>`

            // will be displayed thanks to the 'moveend' event code above
            this.popup = new mapboxgl.Popup({
                closeButton: false,
                focusAfterOpen: false,
                offset: [0, -8],
            })
                .setLngLat(coordinates)
                .setHTML(html)
        }
    }
}

